<script setup>
import {computed} from 'vue';import {simulateQueue} from '../sim/models/queue.mjs';import {useLabSession} from '../sim/session.mjs';
const props=defineProps({focus:{type:String,default:'sync'}});const s=useLabSession('async');const r=computed(()=>simulateQueue({arrivalRate:s.arrival,workerRate:s.workerRate,workers:s.workers,async:s.asyncMode,seconds:10}));
</script><template><section class="sim-lab"><div class="sim-controls"><div><span>工作進來：{{s.arrival}} /s</span><input v-model.number="s.arrival" type="range" min="100" max="2000" step="100" aria-label="每秒進入的工作數"></div><div v-if="props.focus==='capacity'||props.focus==='transfer'"><span>Worker</span><div class="sim-segment"><button v-for="n in [1,2,4]" :key="n" :aria-pressed="s.workers===n" @click="s.workers=n">{{n}} 個</button></div><small>每個 worker 約 {{s.workerRate}} 件/s</small></div><div v-if="props.focus==='sync'||props.focus==='states'||props.focus==='transfer'"><span>通知是否留在 request path</span><div class="sim-segment"><button :aria-pressed="!s.asyncMode" @click="s.asyncMode=false">同步等待</button><button :aria-pressed="s.asyncMode" @click="s.asyncMode=true">非同步排隊</button></div></div></div><div class="sim-system"><div class="sim-node"><b>Order API</b><span>{{s.arrival}} req/s</span></div><div class="sim-arrow">→</div><div :class="['sim-node',{'is-warning':r.queueDepth>0,'is-critical':r.queueDepth>5000}]"><b>{{s.asyncMode?'Queue':'Notification call'}}</b><span>{{s.asyncMode?r.queueDepth+' 件等待':'request 等待結果'}}</span></div><div class="sim-arrow">→</div><div :class="['sim-node',{'is-critical':r.overloaded}]"><b>Worker / Provider</b><span>capacity {{r.capacity}} /s</span></div></div><div class="sim-metrics"><div><span>使用者等回覆</span><strong>{{r.requestLatency}} ms</strong></div><div><span>工作真正完成</span><strong>{{r.completionLatency}} ms</strong></div><div :class="{'is-bad':r.queueDepth>0}"><span>10 秒後 backlog</span><strong>{{r.queueDepth}}</strong></div><div><span>處理能力</span><strong>{{r.processedPerSec}} /s</strong></div></div><div :class="['sim-consequence',{'is-bad':r.overloaded}]"><strong>{{r.overloaded?'工作進來比做完更快':'目前 capacity 足夠'}}</strong><p v-if="s.asyncMode">非同步讓 request 可以先回覆，但工作完成時間沒有憑空消失。當工作流入速度長期高於處理能力，queue 只會把等待累積起來。</p><p v-else>同步模式把 provider 的處理時間留在使用者等待路徑上。切成非同步，再比較「回覆快」和「工作完成快」是不是同一件事。</p></div></section></template>